    </main><footer class="footer"><div class="footer-top"><a class="brand" href="<?=e(url())?>"><span class="brand-mark">c<span>c</span></span><span>CampusConnect<small>YOUR NEXT CHAPTER STARTS HERE.</small></span></a><p>Less scrolling. More showing up.<br>Find your kind of campus life.</p><div><a href="<?=e(url('clubs'))?>">Find a club</a><a href="<?=e(url('events'))?>">Find an event</a></div><div><a href="<?=e(url('help'))?>">Help &amp; getting started</a><a href="<?=e(url('contact'))?>">Get in touch</a><a href="<?=e(url('privacy'))?>">Privacy & your data</a></div></div><div class="footer-bottom"><span>© <?=date('Y')?> CampusConnect · A student community project</span><span>Built for belonging. <?=icon('star')?></span></div></footer></body></html><?php }
function page_heading(string $eyebrow, string $title, string $description, string $extra=''): void { ?><section class="page-heading"><div><div class="eyebrow"><?=e($eyebrow)?></div><h1><?=e($title)?></h1><p><?=e($description)?></p></div><?=$extra?></section><?php }
function empty_state(string $title, string $description, string $link='', string $label='Explore clubs'): void { ?><div class="empty panel"><?=icon('star')?><h3><?=e($title)?></h3><p><?=e($description)?></p><?php if ($link): ?><a class="btn btn-small" href="<?=e($link)?>"><?=e($label)?> <?=icon('arrow')?></a><?php endif; ?></div><?php }
function dashboard_nav(string $active): void { ?><nav class="tabs" aria-label="Account navigation"><a class="<?=$active==='dashboard'?'active':''?>" href="<?=e(url('dashboard'))?>"><?=icon('grid')?> My dashboard</a><a class="<?=$active==='profile'?'active':''?>" href="<?=e(url('profile'))?>">Profile & security</a><?php if(community_account((int)user()['id'])): ?><a class="<?=$active==='community-leaders'?'active':''?>" href="<?=e(url('community-leaders'))?>">Community leaders</a><?php endif; ?><?php if(user()['role']==='admin'): ?><a class="<?=$active==='admin'?'active':''?>" href="<?=e(url('admin'))?>">Campus administration</a><?php endif; ?></nav><?php }
function text_field(string $label, string $name, string $type='text', string $value='', string $extra=''): void { ?><label class="field"><span><?=e($label)?></span><input type="<?=e($type)?>" name="<?=e($name)?>" value="<?=$type==='password'?'':old($name,$value)?>" <?=$extra?>></label><?php }
function textarea_field(string $label, string $name, string $value='', int $max=3000): void { ?><label class="field"><span><?=e($label)?></span><textarea name="<?=e($name)?>" rows="5" maxlength="<?=$max?>" required><?=old($name,$value)?></textarea></label><?php }
